	private void commitQuads(long[][] quads) throws IOException {
		tripleStore.startTransaction();
		for (long[] quad : quads) {
			if (quad[5] == 1) {
				tripleStore.storeTriple(quad[0], quad[1], quad[2], quad[3], quad[4] == 1);
			} else {
				tripleStore.removeTriplesByContext(quad[0], quad[1], quad[2], quad[3], quad[4] == 1, removed -> {
				});
			}
		}
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
	}

	private static long[] add(long s, long p, long o, long c, boolean explicit) {
		return new long[] { s, p, o, c, explicit ? 1 : 0, 1 };
	}

	private static long[] remove(long s, long p, long o, long c, boolean explicit) {
		return new long[] { s, p, o, c, explicit ? 1 : 0, 0 };
	}

	private void awaitApplier() {
		store.pauseApplierForTest(false);
	}

	private void recreateStore(Map<String, String> properties) {
		if (store != null) {
			store.close();
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name)
						? "true"
						: properties.get(name),
				4);
		store = new LmdbDirectAdjacencyStore(tripleStore, null, new AtomicBoolean(false), options);
		tripleStore.setDirectAdjacencyCommitHooks(store.commitListener(), store.newCommitDelta());
	}

	private List<long[]> probe(LmdbAdjacencyReadView view, long s, long p, long o, long c, boolean explicit)
			throws IOException {
		RecordIterator it = store.tryOpen(view, null, s, p, o, c, explicit);
		assertThat(it).as("probe %d/%d/%d must be served", s, p, o).isNotNull();
		List<long[]> rows = new ArrayList<>();
		try {
			long[] quad;
			while ((quad = it.next()) != null) {
				rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
						quad[TripleIndex.OBJ_IDX], Math.max(0, quad[TripleIndex.CONTEXT_IDX]) });
			}
		} finally {
			it.close();
		}
		return rows;
	}

	private void assertDeclined(LmdbAdjacencyReadView view, long s, long p, long o, long c, boolean explicit)
			throws IOException {
		assertThat(store.tryOpen(view, null, s, p, o, c, explicit)).isNull();
	}

